OUT.mkdir(parents=True, exist_ok=True)
for old, slug, title, topic, desc, stay, date in P:
    fm = ["---", f"title: {json.dumps(title)}", f"description: {json.dumps(desc)}", f"topic: {topic}"]
    if date: fm.append(f"pubDate: {date}")
    if stay: fm.append(f"relatedStay: {stay}")
    fm += [f"legacyPath: /blog/{old}/", "imported: false", "---", "",
           "<!-- Body is filled by `npm run import:wp`. Until then the page links to the original. -->", ""]
    (OUT / f"{slug}.md").write_text("\n".join(fm))
    assert 70 <= len(desc) <= 170, (slug, len(desc))
